-- Online Examination System: Question Bank import
-- Adds 3,150 questions: 350 to the existing DSA bank and 400 to each
-- of the other seven existing subjects. Target total: 3,200.
-- Subject matching uses the exact subject_name, not assumed numeric IDs.
-- Does not delete or update existing questions.
-- Exact duplicate question text within the same subject is skipped.
-- No difficulty column is used.

USE online_exam_system;

CREATE TEMPORARY TABLE IF NOT EXISTS question_bank_import (
  subject_name VARCHAR(150) NOT NULL,
  topic VARCHAR(150) NOT NULL,
  question TEXT NOT NULL,
  option_a VARCHAR(500) NOT NULL,
  option_b VARCHAR(500) NOT NULL,
  option_c VARCHAR(500) NOT NULL,
  option_d VARCHAR(500) NOT NULL,
  correct_answer ENUM('A','B','C','D') NOT NULL
) ENGINE=InnoDB;

DELETE FROM question_bank_import;

































SELECT s.id, i.topic, i.question, i.option_a, i.option_b, i.option_c, i.option_d, i.correct_answer
FROM question_bank_import i
JOIN subjects s ON s.subject_name = i.subject_name
WHERE NOT EXISTS (
  SELECT 1 FROM question_bank qb
  WHERE qb.subject_id = s.id AND qb.question = i.question
);

SELECT s.id, s.subject_name, COUNT(qb.id) AS total_questions
FROM subjects s
LEFT JOIN question_bank qb ON qb.subject_id = s.id
GROUP BY s.id, s.subject_name
ORDER BY s.subject_name;

SELECT COUNT(*) AS total_questions_in_question_bank
FROM question_bank;

-- Expected final count: 400 for each of the 8 subjects; 3,200 overall,
-- assuming DSA currently has exactly 50 and the other seven are empty.
